INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Beschaffungsmanagement > Vertragssarten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl von Vertragssarten im Beschaffungsmanagement immer rechtliche Vorgaben berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Rahmenbedingungen sind bindend"}, {"text": "Nein", "correct": false, "because": "Rechtliche Aspekte sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Vertragssarten im Beschaffungsmanagement ohne Rücksicht auf die Lieferbedingungen gewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Lieferbedingungen beeinflussen Vertragstyp"}, {"text": "Ja", "correct": false, "because": "Bedingungen sind relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Kaufvertrag die einzige Vertragssart im Beschaffungsmanagement?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt verschiedene Vertragssarten"}, {"text": "Ja", "correct": false, "because": "Vielfalt an Verträgen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Vertragssarten im Beschaffungsmanagement ohne Rücksicht auf die Zahlungsbedingungen festgelegt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Zahlungsbedingungen sind Vertragsbestandteil"}, {"text": "Ja", "correct": false, "because": "Zahlungsbedingungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Rahmenverträge im Beschaffungsmanagement nur für kurzfristige Beschaffungen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Rahmenverträge sind oft langfristig"}, {"text": "Ja", "correct": false, "because": "Langfristige Nutzung üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vertragssart wird typischerweise für einmalige Beschaffungen verwendet?', 3, '[{"text": "Kaufvertrag", "correct": true, "because": "Für einzelne Käufe geeignet"}, {"text": "Rahmenvertrag", "correct": false, "because": "Langfristig"}, {"text": "Leasingvertrag", "correct": false, "because": "Für Miete"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vertragssart eignet sich für wiederkehrende Lieferungen?', 2, '[{"text": "Rahmenvertrag", "correct": true, "because": "Regelt wiederholte Beschaffungen"}, {"text": "Werkvertrag", "correct": false, "because": "Für Dienstleistungen"}, {"text": "Kaufvertrag", "correct": false, "because": "Einmalig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Wahl der Vertragssart entscheidend?', 2, '[{"text": "Beschaffungsbedarf", "correct": true, "because": "Bestimmt Vertragsform"}, {"text": "Farbe des Produkts", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferantengröße", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vertragssart wird für die Erstellung eines individuellen Produkts genutzt?', 3, '[{"text": "Werkvertrag", "correct": true, "because": "Für spezifische Leistungen"}, {"text": "Kaufvertrag", "correct": false, "because": "Für fertige Produkte"}, {"text": "Rahmenvertrag", "correct": false, "because": "Für wiederkehrende Lieferungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil eines Rahmenvertrags im Beschaffungsmanagement?', 2, '[{"text": "Kosteneinsparung", "correct": true, "because": "Durch langfristige Konditionen"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Nicht primär"}, {"text": "Minimale Dokumentation", "correct": false, "because": "Nicht Vorteil"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vertragssarten werden im Beschaffungsmanagement häufig genutzt?', 4, '[{"text": "Kaufvertrag", "correct": true, "because": "Für einmalige Käufe"}, {"text": "Rahmenvertrag", "correct": true, "because": "Für wiederkehrende Lieferungen"}, {"text": "Werkvertrag", "correct": true, "because": "Für individuelle Leistungen"}, {"text": "Transportvertrag", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl der Vertragssart?', 3, '[{"text": "Beschaffungsbedarf", "correct": true, "because": "Bestimmt Vertragszweck"}, {"text": "Lieferbedingungen", "correct": true, "because": "Beeinflussen Vertrag"}, {"text": "Zahlungsbedingungen", "correct": true, "because": "Finanzielle Aspekte"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Werkvertrag im Beschaffungsmanagement?', 3, '[{"text": "Individuelle Anpassung", "correct": true, "because": "Spezifische Leistungen"}, {"text": "Qualitätskontrolle", "correct": true, "because": "Ergebnis garantiert"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Wahl der Vertragssart auftreten?', 4, '[{"text": "Unklare Bedingungen", "correct": true, "because": "Führt zu Streit"}, {"text": "Rechtliche Risiken", "correct": true, "because": "Verstoß gegen Gesetze"}, {"text": "Kostenüberschreitung", "correct": true, "because": "Falsche Kalkulation"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei einem Kaufvertrag wichtig?', 3, '[{"text": "Kaufpreis", "correct": true, "because": "Finanzielle Grundlage"}, {"text": "Lieferfrist", "correct": true, "because": "Zeitlicher Rahmen"}, {"text": "Garantieleistungen", "correct": true, "because": "Sichert Qualität"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Kaufvertrag wird für einmalige Beschaffungen genutzt. b) Rahmenverträge sind nur kurzfristig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kauf ja, Rahmen langfristig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Werkverträge eignen sich für individuelle Leistungen. b) Lieferbedingungen sind bei Vertragssarten irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Werk ja, Bedingungen wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Rahmenverträge bieten Kosteneinsparungen durch langfristige Konditionen. b) Kaufverträge sind für wiederkehrende Lieferungen ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rahmen ja, Kauf einmalig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Rechtliche Vorgaben beeinflussen die Wahl der Vertragssart. b) Zahlungsbedingungen sind bei Verträgen unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Recht ja, Zahlung wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Vertragssarten hängen vom Beschaffungsbedarf ab. b) Im Beschaffungsmanagement gibt es nur eine Vertragssart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bedarf ja, Vielfalt vorhanden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

